class MinStackNaive {
    private Deque<Integer> stack = new ArrayDeque<>();
    private int min = Integer.MAX_VALUE;

    public void push(int val) {
        stack.push(val);
        min = Math.min(min, val);   // can't be undone on pop
    }

    public void pop() {
        stack.pop();                // min is now possibly stale
    }

    public int top() { return stack.peek(); }

    public int getMin() { return min; }   // WRONG after pops
}

